import datetime

def age_at_admission(row):
    birth = cell('Registrations', row, 'B')
    admission = cell('Registrations', row, 'C')
    if isinstance(birth, datetime.datetime) and isinstance(admission, datetime.datetime):
        return (admission - birth).days
    return None

r_list = rows('Registrations')
if r_list:
    ages = []
    for r in r_list[1:]: # Skip header
        a = age_at_admission(r)
        if a is not None:
            ages.append((a, cell('Registrations', r, 'A')))
    if ages:
        oldest = max(ages, key=lambda x: x[0])
        result = oldest[1]
    else:
        result = None
else:
    result = None

import datetime

def get_age(row_idx):
    birth_str = cell('Registrations', 'B' + str(row_idx))
    admit_str = cell('Registrations', 'C' + str(row_idx))
    if isinstance(birth_str, datetime.datetime) and isinstance(admit_str, datetime.datetime):
        return (admit_str - birth_str).days
    return None

r_list = rows('Registrations')
if r_list:
    candidates = []
    for idx in r_list[1:]: # Skip header row 1
        age = get_age(idx)
        if age is not None:
            name = cell('Registrations', 'A' + str(idx))
            candidates.append((age, name))

    if candidates:
        # Sort by age descending to find oldest
        candidates.sort(key=lambda x: x[0], reverse=True)
        result = candidates[0][1]
    else:
        result = None
else:
    result = None
